"""電子標單 XML 的完整模型：讀進來再寫出去不掉資料（M3 寫入那一路用）。

`etender.py` 的 `Budget` 只抽詳細表樹給 MCP 工具排版，值也去掉了前後空白；這裡另外保留
整份文件，寫出器（`writer.py`）照這個模型寫回，跟 PCCES 匯出檔只差來源四個屬性。

用 expat 自己建樹、不開命名空間處理：ElementTree 分不出 CDATA、也會改寫前綴，
PCCES 匯出檔的 `InfoSummary` 是 CDATA（Class01 還是空的 CDATA），前綴是 `mml:`。
"""

from __future__ import annotations

import xml.parsers.expat
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Iterator

ETENDER_NS = "http://pcstd.pcc.gov.tw/2003/eTender"
ROOT_TAG = "ETenderSheet"
ITEM_TAGS = ("PayItem", "WorkItem")

# 交換標準（PCCES 內附 eTenderSheet.1.J.2004.D.xsd）規定的前段順序；GrandTotalInformation
# 之後的 MaterialData、GPSLocation、InfoSummary、ExtendibleData 原樣放進 extensions
_LEADING = ("TenderInformation", "DetailList", "CostBreakdownList", "ResourceList", "GrandTotalInformation")
_OPTIONAL = ("CostBreakdownList", "ResourceList")


@dataclass
class Node:
    """通用 XML 元素：名稱含前綴原樣保留（例 `mml:math`），屬性照原順序。

    `text` 是葉節點的原文，不去空白（PCCES 用空白補滿欄寬，例如 200 個空白的英文名稱）；
    有子元素的節點 `text` 一律是 None，縮排由寫出器重產。
    """

    tag: str
    attrs: dict[str, str] = field(default_factory=dict)
    text: str | None = None
    cdata: bool = False
    children: list[Node] = field(default_factory=list)

    def find(self, tag: str, **attrs: str) -> Node | None:
        return next(iter(self.findall(tag, **attrs)), None)

    def findall(self, tag: str, **attrs: str) -> list[Node]:
        return [c for c in self.children if c.tag == tag and all(c.attrs.get(k) == v for k, v in attrs.items())]


@dataclass
class Item:
    """詳細表的 PayItem，或單價分析、資源統計的 WorkItem。

    `fields` 是子項以外的子元素（Description、Unit、Quantity、Price、Amount、Remark、Percent、
    人機料雜單價與比例、mml:math），照原順序；`children` 是子項。交換標準規定子項排在最後。
    """

    tag: str
    attrs: dict[str, str] = field(default_factory=dict)
    fields: list[Node] = field(default_factory=list)
    children: list[Item] = field(default_factory=list)

    def get(self, tag: str, language: str | None = None) -> Node | None:
        for n in self.fields:
            if n.tag == tag and (language is None or n.attrs.get("language", "zh-TW") == language):
                return n
        return None

    def value(self, tag: str, language: str | None = None) -> str | None:
        n = self.get(tag, language)
        return None if n is None else n.text or ""

    def decimal(self, tag: str) -> Decimal | None:
        s = (self.value(tag) or "").strip()
        return Decimal(s) if s else None

    @property
    def key(self) -> str:
        """PayItem 的 itemKey 或 WorkItem 的 itemCode，錯誤訊息用來指出是哪一列。"""
        return self.attrs.get("itemKey", self.attrs.get("itemCode", ""))


@dataclass
class ItemList:
    """DetailList、CostBreakdownList 或 ResourceList（後者 WorkItem 之後還可接 PayItem）。"""

    tag: str
    attrs: dict[str, str] = field(default_factory=dict)
    items: list[Item] = field(default_factory=list)

    def iter_items(self) -> Iterator[tuple[int, Item]]:
        """深度優先走訪，回傳（層級, 項目），頂層為 0。"""

        def walk(items: list[Item], level: int) -> Iterator[tuple[int, Item]]:
            for it in items:
                yield level, it
                yield from walk(it.children, level + 1)

        yield from walk(self.items, 0)


@dataclass
class ETenderDocument:
    """一份電子標單（預算書）的全部內容。"""

    root_attrs: dict[str, str]
    tender_information: Node
    detail_list: ItemList
    cost_breakdown_list: ItemList | None
    resource_list: ItemList | None
    grand_total: Node
    extensions: list[Node] = field(default_factory=list)

    @property
    def contract_no(self) -> str:
        return self.tender_information.attrs.get("contractNo", "").strip()

    def title(self, language: str = "zh-TW") -> str:
        n = self._title_node(language)
        return "" if n is None else (n.text or "").strip()

    def set_title(self, text: str, language: str = "zh-TW") -> None:
        n = self._title_node(language)
        if n is None:
            raise ValueError(f"TenderInformation 沒有 language={language} 的 ContractTitle")
        n.text = text

    def _title_node(self, language: str) -> Node | None:
        for n in self.tender_information.findall("ContractTitle"):
            if n.attrs.get("language", "zh-TW") == language:
                return n
        return None

    @property
    def total_amount(self) -> Decimal | None:
        n = self.grand_total.find("TotalAmount")
        s = (n.text or "").strip() if n is not None else ""
        return Decimal(s) if s else None


# ---------- 解析 ----------


@dataclass
class _Frame:
    node: Node
    parts: list[str] = field(default_factory=list)
    plain: list[str] = field(default_factory=list)
    cdata_seen: bool = False


def _unsupported(what: str):
    def handler(*_args):
        raise ValueError(f"檔內有{what}，寫出器不保留它，不能拿這份檔重產")

    return handler


def _parse_tree(data: bytes) -> Node:
    p = xml.parsers.expat.ParserCreate()  # 不給 namespace_separator：前綴與 xmlns 宣告原樣留下
    p.ordered_attributes = True
    p.buffer_text = True
    stack: list[_Frame] = []
    done: list[Node] = []
    in_cdata = False

    def start(name: str, attrs: list[str]) -> None:
        node = Node(name, dict(zip(attrs[::2], attrs[1::2])))
        if stack:
            stack[-1].node.children.append(node)
        stack.append(_Frame(node))

    def end(name: str) -> None:
        f = stack.pop()
        n = f.node
        if n.children:
            # 子元素之間只准有縮排空白；有字就是混合內容，重排縮排會弄丟
            if f.cdata_seen or "".join(f.parts).strip():
                raise ValueError(f"<{name}> 同時有文字與子元素（混合內容），寫出器無法原樣重現")
        elif f.cdata_seen:
            if "".join(f.plain):
                raise ValueError(f"<{name}> 混用 CDATA 與一般文字，寫出器無法原樣重現")
            n.text, n.cdata = "".join(f.parts), True
        elif f.parts:
            n.text = "".join(f.parts)
        if not stack:
            done.append(n)

    def chars(s: str) -> None:
        if not stack:
            return
        f = stack[-1]
        f.parts.append(s)
        if not in_cdata:
            f.plain.append(s)

    def cdata_start() -> None:
        nonlocal in_cdata
        in_cdata = True
        if stack:
            stack[-1].cdata_seen = True

    def cdata_end() -> None:
        nonlocal in_cdata
        in_cdata = False

    p.StartElementHandler = start
    p.EndElementHandler = end
    p.CharacterDataHandler = chars
    p.StartCdataSectionHandler = cdata_start
    p.EndCdataSectionHandler = cdata_end
    p.CommentHandler = _unsupported("註解（<!-- -->）")
    p.ProcessingInstructionHandler = _unsupported("處理指令（<? ?>）")
    p.StartDoctypeDeclHandler = _unsupported(" DOCTYPE 宣告")
    try:
        p.Parse(data, True)
    except xml.parsers.expat.ExpatError as exc:
        raise ValueError(f"不是格式正確的 XML：{exc}") from exc
    return done[0]


def _item(n: Node) -> Item:
    if n.text is not None:
        raise ValueError(f"<{n.tag}> 沒有子元素卻有文字，不像 PCCES 的項目")
    it = Item(n.tag, n.attrs)
    for c in n.children:
        if c.tag in ITEM_TAGS:
            it.children.append(_item(c))
        elif it.children:
            # 交換標準規定子項排最後；寫出器照「欄位→子項」寫，先放子項就會被改順序
            raise ValueError(f"{n.tag} {it.key.strip()} 的子項之後又出現 <{c.tag}>，順序跟交換標準不同")
        else:
            it.fields.append(c)
    return it


def _item_list(n: Node) -> ItemList:
    lst = ItemList(n.tag, n.attrs)
    for c in n.children:
        if c.tag not in ITEM_TAGS:
            raise ValueError(f"<{n.tag}> 底下出現不認得的 <{c.tag}>，只應該有 PayItem／WorkItem")
        lst.items.append(_item(c))
    return lst


def parse_document(source: str | Path | bytes) -> ETenderDocument:
    """讀一份 PCCES 電子標單 XML（路徑或檔案內容），結構不合交換標準就丟 ValueError。"""
    data = source if isinstance(source, bytes) else Path(source).read_bytes()
    root = _parse_tree(data)
    if root.tag != ROOT_TAG:
        raise ValueError(f"不是 PCCES 電子標單 XML：根節點是 {root.tag}，應為 {ROOT_TAG}")
    if root.attrs.get("xmlns") != ETENDER_NS:
        raise ValueError(f"根節點的預設命名空間不是 {ETENDER_NS}，不是 PCCES 電子標單 XML")

    sections: dict[str, Node] = {}
    rest = list(root.children)
    for tag in _LEADING:
        if rest and rest[0].tag == tag:
            sections[tag] = rest.pop(0)
        elif tag not in _OPTIONAL:
            got = rest[0].tag if rest else "（沒有了）"
            raise ValueError(f"ETenderSheet 這個位置應該是 <{tag}>，實際是 <{got}>：缺節點或順序跟交換標準不同")
    for n in rest:
        if n.tag in _LEADING:
            raise ValueError(f"<{n.tag}> 出現在 GrandTotalInformation 之後，順序跟交換標準不同")

    cbl = sections.get("CostBreakdownList")
    res = sections.get("ResourceList")
    return ETenderDocument(
        root_attrs=root.attrs,
        tender_information=sections["TenderInformation"],
        detail_list=_item_list(sections["DetailList"]),
        cost_breakdown_list=_item_list(cbl) if cbl is not None else None,
        resource_list=_item_list(res) if res is not None else None,
        grand_total=sections["GrandTotalInformation"],
        extensions=rest,
    )
